import { parseFormula, collectDeps } from './formula.js'
import { evaluateAll, formatValue } from './eval.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

export const ADDR = /^([A-Za-z]{1,2})([0-9]{1,3})$/

const cells = new Map()
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^[^ \t]*/.exec(line)
  const addrText = m[0]
  const rest = line.slice(addrText.length).replace(/^[ \t]+/, '')
  const am = ADDR.exec(addrText)
  const addr = addrText.toUpperCase()
  if (!am || Number(am[2]) < 1) fail(`error: line ${i + 1}: invalid cell address ${addr}`)
  if (cells.has(addr)) fail(`error: line ${i + 1}: cell ${addr} is declared twice`)
  cells.set(addr, rest)
})

function colIndex(letters) {
  let n = 0
  for (const c of letters) n = n * 26 + (c.charCodeAt(0) - 64)
  return n
}
function sortKey(a) {
  const m = ADDR.exec(a)
  return [colIndex(m[1]), Number(m[2])]
}
function cmpAddr(a, b) {
  const x = sortKey(a)
  const y = sortKey(b)
  return x[0] - y[0] || x[1] - y[1]
}

const addrs = [...cells.keys()].sort(cmpAddr)
const out = []
if (mode === 'values') {
  const results = evaluateAll(cells)
  for (const a of addrs) out.push(`${a}=${formatValue(results.get(a))}`)
} else {
  for (const a of addrs) {
    const content = cells.get(a)
    let line = a + ':'
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (ast) {
        const deps = [...collectDeps(ast)].sort(cmpAddr)
        for (const d of deps) line += ' ' + d
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

