export function colIndex(letters) {
  let n = 0
  for (const c of letters.toUpperCase()) n = n * 26 + (c.charCodeAt(0) - 64)
  return n
}
export function colName(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  return String.fromCharCode(64 + Math.floor((n - 1) / 26)) + String.fromCharCode(65 + ((n - 1) % 26))
}

// Returns {col,row} or null when outside the addressable range.
export function parseAddr(word) {
  const m = ADDR.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1]), row }
}

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { toks.push({ k: 'op', v: two }); i += 2; continue }
    if ('^*/+-=<>(),:'.includes(c)) { toks.push({ k: 'op', v: c }); i++; continue }
    return null
  }
  return toks
}

class Fail extends Error {}

// Returns an AST (with .misplaced flag at the root) or null when the grammar rejects the text.
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  let misplaced = false
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const peekOp = () => (p < toks.length && toks[p].k === 'op' ? toks[p].v : null)

  function cmp() {
    let l = add()
    for (;;) {
      const o = peekOp()
      if (o && ['=', '<>', '<', '<=', '>', '>='].includes(o)) {
        p++
        l = { t: 'bin', op: o, l, r: add() }
      } else return l
    }
  }
  function add() {
    let l = mul()
    for (;;) {
      const o = peekOp()
      if (o === '+' || o === '-') { p++; l = { t: 'bin', op: o, l, r: mul() } } else return l
    }
  }
  function mul() {
    let l = pow()
    for (;;) {
      const o = peekOp()
      if (o === '*' || o === '/') { p++; l = { t: 'bin', op: o, l, r: pow() } } else return l
    }
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    const o = peekOp()
    if (o === '-' || o === '+') { p++; return { t: 'un', op: o, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new Fail()
    const t = toks[p]
    if (t.k === 'num') { p++; return { t: 'num', v: t.v } }
    if (t.k === 'op') {
      if (t.v === '(') {
        p++
        const e = cmp()
        if (!isOp(')')) throw new Fail()
        p++
        return e
      }
      throw new Fail()
    }
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw new Fail()
        }
      }
      return { t: 'call', name: t.v.toUpperCase(), args }
    }
    const up = t.v.toUpperCase()
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw new Fail()
      const w2 = toks[p].v
      p++
      if (isOp('(')) throw new Fail()
      return { t: 'range', a: t.v, b: w2, direct: false }
    }
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', w: t.v }
  }
  function arg() {
    const e = cmp()
    if (e.t === 'range') e.direct = true
    return e
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    const mark = (n) => {
      if (!n) return
      if (n.t === 'range' && !n.direct) misplaced = true
      if (n.t === 'bin') { mark(n.l); mark(n.r) }
      if (n.t === 'un') mark(n.e)
      if (n.t === 'call') n.args.forEach(mark)
    }
    mark(e)
    return { t: 'root', e, misplaced }
  } catch (err) {
    if (err instanceof Fail) return null
    throw err
  }
