  }
  function unary() {
    const o = peekOp()
    if (o === '-' || o === '+') { p++; return { t: 'un', op: o, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new Fail()
    const t = toks[p]
    if (t.k === 'num') { p++; return { t: 'num', v: t.v } }
    if (t.k === 'op') {
      if (t.v === '(') {
        p++
        const e = cmp()
        if (!isOp(')')) throw new Fail()
        p++
        return e
      }
      throw new Fail()
    }
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw new Fail()
        }
      }
      return { t: 'call', name: t.v.toUpperCase(), args }
    }
    const up = t.v.toUpperCase()
