export function rangeCells(r) {
  const a = parseAddr(r.a)
  const b = parseAddr(r.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) {
    for (let w = Math.min(a.row, b.row); w <= Math.max(a.row, b.row); w++) out.push(colName(c) + w)
