  function argValues(n) {
    if (n.t === 'range') {
      const cs = rangeCells(n)
      if (!cs) return [err('#REF!')]
      return cs.map(cellValue)
    }
    return [ev(n)]
  }

  function ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { k: 'bool', v: n.v }
      case 'ref': return refValue(n.w)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = ev(n.e)
        if (isErr(v)) return v
        const x = toNum(v)
        if (typeof x !== 'number') return x
        return num(n.op === '-' ? -x : x)
      }
      case 'bin': {
        const l = ev(n.l)
        if (isErr(l)) return l
        const r = ev(n.r)
